import { PRODUCTS, SIZE_GUIDE, fmtPrice, normalizeCart, addItem, updateQuantity, removeItem, cartSummary, prepareOrder } from './commerce.js';

import { renderShooting, mountShooting } from './shooting.js';
import { renderProductSlides, mountProductSlides, getProductVariantImage } from './product-slides.js?v=20261024-4';

const app = document.querySelector('#app');
const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = (s = '') => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage = { get(key, fallback) { try { return JSON.parse(localStorage.getItem(`spali:${key}`)) ?? fallback; } catch { return fallback; } }, set(key, value) { try { localStorage.setItem(`spali:${key}`, JSON.stringify(value)); } catch { /* La prueba también funciona sin almacenamiento persistente. */ } } };
const labels = { equipo:'Equipo',padel:'Pareja',entrenamiento:'Individual',mujer:'Mujer',hombre:'Hombre',unisex:'Unisex',camisetas:'Camisetas',shorts:'Shorts',tops:'Tops',mallas:'Mallas',chaquetas:'Chaquetas',sudaderas:'Sudaderas' };
const styles = { enjuego:'En juego',caracter:'Carácter',recortes:'Recortes' };
const shippingLabels = { standard:'Envío estándar',express:'Envío exprés',pickup:'Recogida' };
const getProduct = id => PRODUCTS.find(p => p.id === id);
let cart = normalizeCart(storage.get('cart', []));
let favorites = storage.get('favorites', []);
favorites = Array.isArray(favorites) ? favorites.filter(id => getProduct(id)) : [];
