let shipping = 'standard';
let orders = storage.get('orders', []);
orders = Array.isArray(orders) ? orders.filter(o => o && o.simulation === true && typeof o.id === 'string' && o.customer && typeof o.customer.name === 'string' && o.summary && Number.isFinite(o.summary.total) && Array.isArray(o.items)).slice(0,20) : [];
