  truck:'<path d="M2 4h12v13H2V4Zm12 6h5l3 4v3h-8"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="18" r="3"/>',
  return:'<path d="M4 9h10a6 6 0 1 1 0 12H9M9 3 3 9l6 6"/>',
  lock:'<rect x="5" y="10" width="14" height="12" rx="1"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',
  filter:'<path d="M3 6h18M6 12h12M9 18h6"/>',
  mail:'<rect x="2" y="4" width="20" height="16" rx="1"/><path d="m2 5 10 8L22 5"/>',
