  const copy = view==='caracter' ? ['TODO EMPIEZA','EN TI.','La disciplina se entrena. Tu forma de ser, se lleva.'] : view==='recortes' ? ['LO QUE LLEVAS','TAMBIÉN JUEGA.','Una misma actitud. Todas tus formas de moverte.'] : ['A TU','MANERA.','En equipo, en pareja o a tu manera. El deporte lo pones tú.'];
