function collection(params) {
  const line=params.get('linea')||'', gender=params.get('publico')||'', category=params.get('tipo')||'', search=(params.get('q')||'').slice(0,100), sort=params.get('orden')||'coleccion';
  let list=PRODUCTS.filter(p=>(!line||p.line===line)&&(!gender||p.gender===gender||p.gender==='unisex')&&(!category||p.category===category)&&(!search||`${p.name} ${labels[p.line]} ${labels[p.category]} ${labels[p.gender]}`.toLocaleLowerCase('es').includes(search.toLocaleLowerCase('es'))));
  if(sort==='precio-asc')list.sort((a,b)=>a.price-b.price);else if(sort==='precio-desc')list.sort((a,b)=>b.price-a.price);else if(sort==='nombre')list.sort((a,b)=>a.name.localeCompare(b.name,'es'));
  const title=search?`Resultados para «${esc(search)}»`:line?labels[line]||'Colección':gender?`Colección ${labels[gender]||''}`:'La colección';
  const options=(items,value)=>items.map(([key,label])=>`<option value="${key}" ${key===value?'selected':''}>${label}</option>`).join('');
  return `<div class="shell">${breadcrumb([[title]])}${pageHead(title,'En equipo, en pareja o de forma individual. Encuentra tu forma de llevar SPALI.','12 PIEZAS · TRES MANERAS')}<div class="catalog-layout"><aside class="filters" aria-label="Filtrar la colección"><details class="filter-disclosure" ${window.innerWidth>800?'open':''}><summary>${icon('filter')}Filtrar la colección</summary><form id="filters-form"><div class="filter-heading">${icon('filter')}<h2>Filtrar</h2></div><label class="filter-group">Cómo lo practicas<select name="linea">${options([['','Todas las formas'],['equipo','Equipo'],['padel','Pareja'],['entrenamiento','Individual']],line)}</select></label><label class="filter-group">Colección<select name="publico">${options([['','Todas las personas'],['mujer','Mujer'],['hombre','Hombre'],['unisex','Unisex']],gender)}</select></label><label class="filter-group">Prenda<select name="tipo">${options([['','Todas las prendas'],...Object.entries(labels).filter(([k])=>['camisetas','shorts','tops','mallas','chaquetas','sudaderas'].includes(k))],category)}</select></label><label class="filter-group">Buscar<input type="search" name="q" value="${esc(search)}" placeholder="Camiseta, top, equipo…"></label><button class="button button-outline" type="submit">Aplicar filtros ${icon('arrow')}</button>${a('coleccion','Limpiar filtros','clear-filters')}<div class="filter-note"><span class="eyebrow">COLECCIÓN EN DESARROLLO</span><p>Estas prendas y precios son una propuesta para revisar el diseño de la tienda.</p></div></form></details></aside><section class="catalog-products" aria-label="Productos"><div class="catalog-top"><span role="status">${list.length} ${list.length===1?'prenda':'prendas'}</span><label class="sort-label">Ordenar<select class="sort-select" id="sort-select" aria-label="Ordenar productos">${options([['coleccion','Nuestra selección'],['precio-asc','Precio: menor a mayor'],['precio-desc','Precio: mayor a menor'],['nombre','Nombre']],sort)}</select></label></div>${list.length?productGrid(list):empty('No hemos encontrado esa combinación.','Prueba otra forma de practicar, otro tipo de prenda o una búsqueda más corta.','coleccion','Ver toda la colección')}</section></div></div>`;
}

function productDetail(id,requestedColor='') {
  const p=getProduct(id);if(!p)return notFound();
  const selectedColor=p.colors.some(c=>c.name===requestedColor)?requestedColor:p.colors[0].name;
  return `<div class="shell">${breadcrumb([['Colección','coleccion'],[p.name]])}<section class="product-detail"><div class="product-gallery">${productImage(p,'eager',selectedColor)}<div class="gallery-caption">IMAGEN CONCEPTUAL · ${labels[p.line].toUpperCase()} 01</div><div class="product-thumbs"><button class="active" aria-label="Vista frontal de ${esc(p.name)}">${productImage(p,'lazy',selectedColor)}</button><div class="detail-story">${brandMark()}<p>Tu forma de<br>llevar SPALI.</p></div></div></div><div class="product-info"><span class="eyebrow">${labels[p.line].toUpperCase()} / ${labels[p.gender].toUpperCase()}</span><h1>${p.name}</h1><div class="price-large">${price(p.price)}</div><p class="product-intro">${p.description.split('. ')[0]}.</p><form id="product-form" data-id="${p.id}"><fieldset><legend>Color <span class="selected-color">${esc(selectedColor)}</span></legend><div class="swatch-list">${p.colors.map((c,i)=>`<label class="swatch" style="--swatch:${c.hex}" title="${c.name}"><input type="radio" name="color" value="${c.name}" ${c.name===selectedColor?'checked':''}><span aria-hidden="true"></span><span class="sr-only">${c.name}</span></label>`).join('')}</div></fieldset><fieldset><legend><span>Talla</span>${a('guia-tallas','Guía de tallas','size-guide-link')}</legend><div class="size-list">${p.sizes.map(s=>`<label class="size-button"><input type="radio" name="size" value="${s}" required><span>${s}</span></label>`).join('')}</div></fieldset><div class="personalize"><label class="checkbox-label"><input id="personalize-toggle" type="checkbox" name="personalize"><span>Añade tu nombre <strong>+4,00 €</strong></span></label><div id="personalize-fields" hidden><label class="field" for="custom-name">Nombre para la prenda<input id="custom-name" name="customName" type="text" maxlength="15" placeholder="Ej. ALEX" autocomplete="off"><span class="help">Hasta 15 caracteres. Letras, números y espacios.</span></label><div class="name-preview" aria-label="Vista previa del nombre"><span id="name-preview">TU NOMBRE</span><small>Vista gráfica orientativa</small></div></div></div><div class="product-actions"><label class="qty-control"><span class="sr-only">Cantidad</span><button type="button" data-action="product-qty" data-delta="-1" aria-label="Restar una unidad">${icon('minus')}</button><input name="qty" type="number" min="1" max="10" value="1" aria-label="Cantidad"><button type="button" data-action="product-qty" data-delta="1" aria-label="Sumar una unidad">${icon('plus')}</button></label><button type="submit" class="button add-button">Añadir a la bolsa ${icon('bag')}</button><button type="button" class="icon-button detail-favorite ${favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-pressed="${favorites.includes(p.id)}" aria-label="${favorites.includes(p.id)?'Quitar de':'Añadir a'} favoritos">${icon('heart')}</button></div><p class="error" id="product-error" role="alert"></p></form><p class="product-demo-note">Producto de muestra. Colores, tallaje, precio y acabados se confirmarán para el lanzamiento.</p><div class="accordion"><details open><summary>El diseño</summary><ul>${p.details.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></details><details><summary>Ajuste y tallas</summary><p>${esc(p.fit)}</p>${a('guia-tallas','Consultar las medidas de ejemplo')}</details><details><summary>Cuidados</summary><p>${esc(p.care)}</p></details><details><summary>Envío y personalización</summary><p>En esta prueba puedes elegir envío estándar, exprés o recogida. Los pedidos son simulados y no se realizan cobros ni envíos.</p>${a('envios','Ver condiciones de la vista previa')}</details></div></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">COMPLETA TU JUEGO</span><h2 class="section-title">En la misma línea.</h2></div>${arrowLink('coleccion',`Ver ${labels[p.line]}`,{linea:p.line})}</div>${productGrid(PRODUCTS.filter(q=>q.line===p.line&&q.id!==p.id))}</section></div>`;
}

function empty(title,text,path='coleccion',button='Explorar la colección') {
  return `<div class="empty-state">${brandMark()}<h2>${title}</h2><p>${text}</p>${a(path,`${button}${icon('arrow')}`,'button')}</div>`;
}
function lineItem(line,compact=false) {
  const p=getProduct(line.id);if(!p)return '';
  return `<article class="cart-item ${compact?'cart-item--compact':''}"><a class="cart-item-image" href="${href('producto/'+p.id,{color:line.color})}">${productImage(p,'lazy',line.color)}</a><div class="cart-item-details"><span class="eyebrow">${labels[p.line]}</span><h3>${a('producto/'+p.id,esc(p.name),'',{color:line.color})}</h3><p>${esc(line.color)} / ${esc(line.size)}</p>${line.customName?`<p class="custom-name">Nombre: <strong>${esc(line.customName)}</strong> · +${fmtPrice(4*line.qty)}</p>`:''}<p class="unit-price">A ${fmtPrice(p.price)} por unidad</p>${compact?`<span>Cantidad: ${line.qty}</span>`:`<div class="item-controls"><label class="qty-control"><span class="sr-only">Cantidad de ${esc(p.name)}</span><button data-action="cart-qty" data-key="${esc(line.key)}" data-delta="-1" aria-label="Restar una unidad de ${esc(p.name)}">${icon('minus')}</button><input type="number" min="1" max="10" value="${line.qty}" data-cart-qty="${esc(line.key)}" aria-label="Cantidad de ${esc(p.name)}"><button data-action="cart-qty" data-key="${esc(line.key)}" data-delta="1" aria-label="Sumar una unidad de ${esc(p.name)}">${icon('plus')}</button></label><button class="remove-item" data-action="remove" data-key="${esc(line.key)}">Eliminar</button></div>`}</div><strong class="cart-item-total">${fmtPrice((p.price+(line.customName?4:0))*line.qty)}</strong></article>`;
}
function summaryRows(method=shipping) {
  const s=cartSummary(cart,{shipping:method,code:promo});
  return `<div class="summary-row"><span>Prendas (${s.count})</span><span>${fmtPrice(s.subtotal)}</span></div>${s.personalization?`<div class="summary-row"><span>Personalización</span><span>${fmtPrice(s.personalization)}</span></div>`:''}${s.discount?`<div class="summary-row discount-row"><span>Descuento SPALI10</span><span>−${fmtPrice(s.discount)}</span></div>`:''}<div class="summary-row"><span>${shippingLabels[method]}</span><span>${s.shipping?fmtPrice(s.shipping):'Sin coste'}</span></div><div class="summary-total"><span>Total</span><strong>${fmtPrice(s.total)}</strong></div><p class="help">IVA incluido (${fmtPrice(s.taxIncluded)}). Importes de demostración.</p>`;
}
function coupon() {
  return `<form class="coupon" id="coupon-form"><label for="coupon-code">¿Tienes un código?</label><div><input id="coupon-code" name="code" value="${esc(promo)}" placeholder="Prueba SPALI10" autocomplete="off" maxlength="30"><button type="submit" class="button button-outline">Aplicar</button></div><p class="help" id="coupon-feedback" role="status">${promo==='SPALI10'?'Código SPALI10 aplicado.':'Código de muestra: SPALI10, 10 % sobre las prendas.'}</p></form>`;
}
function cartPage() {
  return `<div class="shell">${breadcrumb([['Tu bolsa']])}${pageHead('Tu bolsa.',cart.length?'Tu próxima jugada empieza aquí.':'Hay sitio para tu siguiente paso.')} ${cart.length?`<div class="cart-layout"><section class="cart-items" aria-label="Prendas en la bolsa"><div class="cart-topline"><span>${cartSummary(cart).count} ${cartSummary(cart).count===1?'artículo':'artículos'}</span>${arrowLink('coleccion','Seguir explorando')}</div>${cart.map(l=>lineItem(l)).join('')}<div class="cart-note">${icon('user')}<p>Podrás continuar como invitado, sin crear una cuenta.</p></div></section><aside class="summary"><h2>Resumen de la bolsa</h2><div id="summary-rows">${summaryRows()}</div>${a('pago',`Continuar con la prueba ${icon('arrow')}`,'button checkout-button')}${coupon()}<p class="help">${icon('lock')}Pedido simulado: no se pedirán datos de tarjeta.</p></aside></div>`:empty('Tu bolsa está esperando.','Encuentra algo que encaje con tu forma de moverte.')}<section class="section"><div class="section-head"><h2 class="section-title">Sigue en juego.</h2>${arrowLink('coleccion','Ver colección')}</div>${productGrid(PRODUCTS.slice(0,4))}</section></div>`;
}

const field=(name,label,type='text',opts={})=>`<label class="field ${opts.wide?'wide':''}" for="${name}">${label}${opts.required===false?' <span class="optional">(opcional)</span>':''}<input id="${name}" name="${name}" type="${type}" ${opts.required===false?'':'required'} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.value?`value="${esc(opts.value)}"`:''} ${opts.inputmode?`inputmode="${opts.inputmode}"`:''} ${opts.pattern?`pattern="${opts.pattern}"`:''} ${opts.maxlength?`maxlength="${opts.maxlength}"`:''}><span class="error" data-error="${name}" role="alert"></span></label>`;
function checkout() {
  if(!cart.length)return `<div class="shell">${pageHead('Vamos paso a paso.')} ${empty('Primero, elige tu prenda.','La bolsa está vacía. Añade una prenda para probar el proceso de compra.')}</div>`;
  return `<div class="shell">${breadcrumb([['Tu bolsa','carrito'],['Finalizar la prueba']])}<div class="checkout-steps" aria-label="Pasos de la compra"><span>01 Bolsa</span><strong>02 Datos y entrega</strong><span>03 Confirmación</span></div>${pageHead('El último paso.','Compra como invitado. En esta vista previa el pedido es de prueba y no se realizan cobros.')}<div class="checkout-layout"><section class="checkout-main"><form id="checkout-form" novalidate><div class="form-card"><div class="form-card-head"><span>01</span><h2>Tus datos</h2><span class="pill">Sin registro</span></div><p class="help">Usa datos ficticios para probar el recorrido. Se guardarán solo en este navegador.</p><div class="form-grid">${field('name','Nombre y apellidos','text',{autocomplete:'name',value:profile?.name||'',wide:true})}${field('email','Correo electrónico','email',{autocomplete:'email',value:profile?.email||''})}${field('phone','Teléfono','tel',{autocomplete:'tel',placeholder:'600 000 000'})}</div></div><div class="form-card"><div class="form-card-head"><span>02</span><h2>Entrega</h2></div><fieldset class="shipping-options"><legend class="sr-only">Método de entrega</legend>${[['standard','Envío estándar','4,90 € · gratis a partir de 75 €'],['express','Envío exprés','7,90 € · gratis a partir de 75 €'],['pickup','Recogida','Sin coste · opción de muestra']].map(([key,title,desc])=>`<label class="shipping-option"><input name="shipping" type="radio" value="${key}" ${key===shipping?'checked':''}><span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</fieldset><p class="help">Umbral aplicado al importe de prendas tras el descuento. Condiciones de demostración.</p><div class="form-grid" id="address-fields">${field('address','Dirección y número','text',{autocomplete:'street-address',placeholder:'Calle Ejemplo 12',wide:true})}${field('postalCode','Código postal','text',{autocomplete:'postal-code',inputmode:'numeric',maxlength:5,placeholder:'41001'})}${field('city','Localidad','text',{autocomplete:'address-level2',placeholder:'Sevilla'})}<div class="field"><span>País</span><div class="static-field">España</div></div></div></div><div class="form-card"><div class="form-card-head"><span>03</span><h2>Pago de prueba</h2>${icon('lock')}</div><div class="payment-demo"><span class="payment-icon">${icon('check')}</span><div><strong>Simulación sin cobro</strong><p>Sin tarjeta, sin cargos y sin envío de productos. Podrás revisar la pantalla de confirmación y el pedido de muestra.</p></div></div></div><label class="checkbox-label checkout-consent"><input type="checkbox" id="consent" name="consent"><span>Entiendo que es un pedido de prueba y he leído la ${a('privacidad','información de privacidad')}.<span class="error" data-error="consent" role="alert"></span></span></label><p class="error" id="checkout-error" role="alert"></p><button class="button place-order" type="submit">Crear pedido de prueba ${icon('arrow')}</button></form></section><aside class="summary"><h2>Tu selección</h2><div class="checkout-items">${cart.map(l=>lineItem(l,true)).join('')}</div><div id="checkout-summary">${summaryRows()}</div>${a('carrito','Modificar mi bolsa','text-link')}<div class="summary-demo">${icon('lock')}<p>Esta compra es una simulación. No reserva existencias ni se transmite a ningún comercio.</p></div></aside></div></div>`;
}

function confirmation(id) {
  const order=orders.find(o=>o.id===id);
  if(!order)return `<div class="shell">${pageHead('Confirmación de pedido.')} ${empty('No hay un pedido de prueba aquí.','Los pedidos de muestra se guardan solo en el navegador en el que los creas.','cuenta','Ver mi espacio')}</div>`;
  return `<div class="shell"><section class="order-success"><div class="success-symbol">${icon('check')}</div><span class="eyebrow">SIMULACIÓN COMPLETADA</span><h1>Ya estás en juego.</h1><p>Tu pedido de prueba está creado, ${esc(order.customer.name.split(' ')[0])}.</p><div class="order-id">${esc(order.id)}</div><p class="help">No se ha realizado ningún cobro ni se ha enviado un correo de confirmación.</p><div class="order-progress"><span class="active">${icon('check')}Datos comprobados</span><span class="active">${icon('check')}Pedido de prueba creado</span><span>Sin envío real</span></div></section><div class="cart-layout"><section class="cart-items"><h2>Tu pedido de muestra</h2>${normalizeCart(order.items).map(l=>lineItem(l,true)).join('')}<div class="order-delivery"><h3>Entrega elegida</h3><p>${shippingLabels[order.shipping]||'Envío de muestra'}</p>${order.shipping!=='pickup'?`<p>${esc(order.customer.address)}<br>${esc(order.customer.postalCode)} ${esc(order.customer.city)}</p>`:''}</div></section><aside class="summary"><h2>Resumen</h2><div class="summary-row"><span>Prendas</span><span>${fmtPrice(order.summary.subtotal)}</span></div>${order.summary.personalization?`<div class="summary-row"><span>Personalización</span><span>${fmtPrice(order.summary.personalization)}</span></div>`:''}${order.summary.discount?`<div class="summary-row"><span>Descuento</span><span>−${fmtPrice(order.summary.discount)}</span></div>`:''}<div class="summary-row"><span>Entrega</span><span>${fmtPrice(order.summary.shipping)}</span></div><div class="summary-total"><span>Total de prueba</span><strong>${fmtPrice(order.summary.total)}</strong></div><button class="button button-outline" data-action="download-order" data-order="${esc(order.id)}">Descargar resumen ${icon('arrow')}</button>${a('coleccion','Volver a la colección','text-link')}${a('cuenta','Ver pedidos de prueba','text-link')}</aside></div></div>`;
}

function favoritesPage() { return `<div class="shell">${breadcrumb([['Favoritos']])}${pageHead('Lo que va contigo.','Guarda las prendas que te gustan y vuelve a ellas cuando quieras.','TUS FAVORITOS')}${favorites.length?productGrid(PRODUCTS.filter(p=>favorites.includes(p.id))):empty('Todavía no has guardado ninguna prenda.','Toca el corazón de cualquier producto para encontrarlo aquí.')}</div>`; }

function account() {
  return `<div class="shell">${breadcrumb([['Mi espacio']])}${pageHead(profile?`Hola, ${esc(profile.name.split(' ')[0])}.`:'Tu espacio SPALI.',profile?'Tu selección y tus pedidos de prueba, en un mismo sitio.':'Entra en el espacio de prueba para revisar el diseño de la cuenta.')}<div class="account-layout"><nav class="account-menu" aria-label="Mi espacio"><a href="#pedidos">Mis pedidos de prueba <span>${orders.length}</span></a>${a('favoritos',`Mis favoritos <span>${favorites.length}</span>`)}${a('carrito','Mi bolsa')}${a('ayuda','¿Te ayudamos?')}${profile?'<button data-action="logout">Salir del espacio de prueba</button>':''}</nav><div class="account-content">${!profile?`<section class="form-card"><span class="eyebrow">ACCESO DE DEMOSTRACIÓN</span><h2>Todo listo para volver.</h2><form id="account-form" class="form-stack">${field('account-name','Tu nombre','text',{placeholder:'Ej. Alex'})}${field('account-email','Tu correo','email',{placeholder:'alex@example.com'})}<button type="submit" class="button">Entrar en modo prueba ${icon('arrow')}</button><p class="help">Esta pantalla prueba el diseño de la cuenta. No crea una cuenta real ni solicita contraseña. Los datos se conservan solo en este navegador.</p><p role="status" class="form-feedback"></p></form></section>`:`<section class="form-card"><span class="eyebrow">TUS DATOS DE PRUEBA</span><h2>${esc(profile.name)}</h2><p>${esc(profile.email)}</p><p class="help">Sesión de demostración local. El acceso real se conectará con WooCommerce.</p></section>`}<section class="section account-orders" id="pedidos"><div class="section-head"><h2 class="section-title">Mis pedidos de prueba</h2></div>${orders.length?orders.map(o=>`<article class="order-card"><div><span class="pill">Pedido simulado</span><h3>${esc(o.id)}</h3><p>${new Date(o.createdAt).toLocaleDateString('es-ES')} · ${normalizeCart(o.items).reduce((n,l)=>n+l.qty,0)} ${normalizeCart(o.items).reduce((n,l)=>n+l.qty,0)===1?'artículo':'artículos'}</p></div><strong>${fmtPrice(o.summary?.total||0)}</strong>${a('confirmacion/'+encodeURIComponent(o.id),`Ver pedido ${icon('arrow')}`,'text-link')}</article>`).join(''):notice('Todavía no has completado ningún pedido de prueba. Puedes hacerlo desde la bolsa sin crear una cuenta.')}</section></div></div></div>`;
}

function story() {
  return `<div class="story-page"><div class="shell">${breadcrumb([['Somos SPALI']])}</div><section class="story-hero"><img src="assets/campana-padel.jpg" alt="Pareja de deportistas en una pista de pádel" width="1536" height="1024"><div class="shell"><span class="eyebrow">SOMOS SPALI SPORTS</span><h1>Tu forma de ser.<br>Tu forma de jugar.</h1></div></section><section class="section shell content-grid"><div><span class="eyebrow">UNA MARCA PROPIA</span><h2 class="section-title">Tu equipo.<br>Tu pista. Tu forma.</h2></div><div class="rich-text"><p>SPALI SPORTS es el proyecto de una marca propia de ropa deportiva. Equipo, Pareja e Individual comparten una misma idea: que cada persona encuentre su manera de vivir el deporte.</p><p>La colección que ves aquí es la propuesta inicial de diseño. Estamos dando forma a las prendas, los tejidos y los detalles antes del lanzamiento.</p></div></section><section class="section shell"><div class="section-head"><h2 class="section-title">Tres maneras de entrar en juego.</h2></div><div class="line-grid">${[['equipo','campana-equipo.jpg','El vínculo que se lleva.'],['padel','campana-padel.jpg','Tu sitio en la pista.'],['entrenamiento','campana-entrenamiento.jpg','Una vez más, contigo.']].map(([line,img,title])=>`<a class="line-card" data-line="${line}" href="${href('coleccion',{linea:line})}"><img src="assets/${img}" alt="${labels[line]}" loading="lazy"><div><span class="eyebrow">${labels[line]}</span><h3>${title}</h3>${icon('arrow')}</div></a>`).join('')}</div></section></div>`;
}

function sizeGuide() {
  return `<div class="shell">${breadcrumb([['Guía de tallas']])}${pageHead('Que encaje contigo.','Una guía clara para elegir con calma.','GUÍA DE TALLAS')}${notice('Tabla de ejemplo para revisar el diseño. Las medidas definitivas se sustituirán por las del fabricante y de cada prenda antes de vender.')}<div class="content-grid section"><div class="size-guide-visual"><div class="measure-figure">${brandMark()}<div class="measure-line chest"><span>01 / Pecho</span></div><div class="measure-line waist"><span>02 / Cintura</span></div><div class="measure-line hips"><span>03 / Cadera</span></div></div></div><div class="rich-text"><h2>Cómo tomar tus medidas</h2><p><strong>01 · Pecho.</strong> Rodea la parte más ancha del pecho con la cinta horizontal.</p><p><strong>02 · Cintura.</strong> Mide el contorno de tu cintura natural sin apretar la cinta.</p><p><strong>03 · Cadera.</strong> Rodea la zona más ancha, con los pies juntos.</p><p>Son medidas corporales de ejemplo, en centímetros. Si estás entre dos tallas, consulta la ficha y el ajuste de la prenda definitiva.</p></div></div><div class="table-wrap"><table class="size-table"><caption>Medidas corporales orientativas de muestra · centímetros</caption><thead><tr><th scope="col">Talla</th><th scope="col">Pecho</th><th scope="col">Cintura</th><th scope="col">Cadera</th></tr></thead><tbody>${SIZE_GUIDE.map(s=>`<tr><th scope="row">${s.size}</th><td>${s.chest}</td><td>${s.waist}</td><td>${s.hips}</td></tr>`).join('')}</tbody></table></div><div class="section support-callout"><div><h2>¿Te ayudamos a elegir?</h2><p>Revisaremos contigo las tallas cuando esté definida la colección.</p></div>${a('contacto',`Hablar con SPALI ${icon('arrow')}`,'button button-outline')}</div></div>`;
}

const faqGroups = [
  ['La colección',[
    ['¿Ya puedo comprar estas prendas?','Esta es una vista previa de diseño. Las imágenes, las referencias y los precios son de muestra. Puedes probar la bolsa y crear pedidos simulados; no se realizan cobros, reservas ni envíos.'],
    ['¿Qué líneas tendrá SPALI?','La propuesta reúne Equipo, Pareja e Individual. El catálogo definitivo y sus características se confirmarán antes del lanzamiento.'],
    ['¿Puedo personalizar una prenda?','En esta prueba puedes añadir un nombre de hasta 15 caracteres, con un suplemento de muestra de 4 € por unidad. La vista gráfica es orientativa.']]],
  ['Tu compra',[
    ['¿Necesito crear una cuenta?','No. El recorrido de compra permite continuar como invitado. La cuenta es opcional.'],
    ['¿Cómo funcionan los envíos en la prueba?','Puedes simular un envío estándar de 4,90 €, exprés de 7,90 € o recogida sin coste. El envío queda a cero cuando las prendas, tras aplicar el descuento, alcanzan 75 €. Son condiciones de demostración.'],
    ['¿Hay un código para probar descuentos?','Sí: SPALI10 aplica un 10 % al importe de las prendas. El suplemento de personalización y el envío no reciben ese descuento.']]],
  ['La vista previa',[
    ['¿Dónde se guardan mis datos?','El carrito, los favoritos y los pedidos de muestra se guardan en el almacenamiento local de este navegador. No se envían a una tienda ni a una plataforma de pagos. Usa datos ficticios.'],
    ['¿Puedo comparar los tres diseños?','Sí. Usa el selector superior para cambiar entre Carácter, En juego y Recortes. La colección, el carrito y todas las páginas mantienen el estilo que elijas.']]],
];
function helpPage() {
  return `<div class="shell">${breadcrumb([['Centro de ayuda']])}${pageHead('Estamos en tu equipo.','Encuentra una respuesta y sigue en juego.','CENTRO DE AYUDA')}<div class="support-grid">${[['guia-tallas','Tu talla','Medidas y ajuste de ejemplo.','user'],['envios','La entrega','Opciones del recorrido de prueba.','truck'],['devoluciones','Cambios','Cómo será esta parte de la tienda.','return']].map(([path,title,text,ic])=>`<a class="contact-card" href="${href(path)}">${icon(ic)}<h2>${title}</h2><p>${text}</p>${icon('arrow')}</a>`).join('')}</div><section class="section faq-list">${faqGroups.map(([title,questions])=>`<div class="faq-group"><h2>${title}</h2><div class="accordion">${questions.map(([q,answer])=>`<details><summary>${q}</summary><p>${answer}</p></details>`).join('')}</div></div>`).join('')}</section><section class="support-callout section"><div><h2>¿Te queda alguna duda?</h2><p>Estamos dando forma a SPALI. Tu opinión cuenta.</p></div>${a('contacto',`Escríbenos ${icon('arrow')}`,'button')}</section></div>`;
}

function contact() {
  return `<div class="shell">${breadcrumb([['Contacto']])}${pageHead('Hablemos de tu juego.','Una pregunta, una idea o un equipo con ganas de ponerse en marcha.','CONTACTO')}<div class="content-grid section"><div class="rich-text"><h2>Te escuchamos.</h2><p>Elige el motivo y deja tu mensaje para comprobar el formulario.</p>${notice('Formulario de staging. No se enviará ningún correo; al terminar verás una confirmación de prueba.')}<div class="contact-details">${icon('pin')}<div><strong>Publipop Soluciones en Merchandising, S.L.</strong><p>Contacto de la marca en preparación.</p></div></div>${arrowLink('ayuda','Consultar el centro de ayuda')}</div><form id="contact-form" class="form-card form-stack">${field('contact-name','Tu nombre')}${field('contact-email','Tu correo electrónico','email')}<label class="field" for="contact-topic">¿Sobre qué quieres hablar?<select id="contact-topic" name="topic"><option>La colección</option><option>Tallas y prendas</option><option>Personalización y equipos</option><option>Mi pedido de prueba</option><option>Otra consulta</option></select></label><label class="field" for="contact-message">Tu mensaje<textarea id="contact-message" name="message" minlength="10" maxlength="2000" rows="5" required placeholder="Cuéntanos…"></textarea></label><label class="checkbox-label"><input name="consent" type="checkbox" required><span>He leído la ${a('privacidad','información de privacidad')}.</span></label><button class="button" type="submit">Probar el formulario ${icon('arrow')}</button><p class="form-feedback" role="status"></p></form></div></div>`;
}

const infoPages = {
  envios:{title:'Cada paso, claro.',eyebrow:'ENVÍOS Y ENTREGA',intro:'Opciones de entrega para revisar el recorrido de compra.',body:`<h2>Entrega en la vista previa</h2><p>Los pedidos de esta web son simulados: no existe un envío físico asociado.</p><div class="delivery-grid"><div><span>01</span><h3>Estándar</h3><strong>4,90 €</strong><p>Importe de muestra para probar el carrito.</p></div><div><span>02</span><h3>Exprés</h3><strong>7,90 €</strong><p>Segunda opción de entrega para comparar el diseño.</p></div><div><span>03</span><h3>Recogida</h3><strong>Sin coste</strong><p>Opción ilustrativa, sin punto de recogida operativo.</p></div></div><h2>El envío de prueba se queda a cero con 75 €</h2><p>Se calcula sobre el importe de las prendas después del descuento, sin incluir personalización. Las zonas, los transportistas y los plazos reales se definirán antes de la apertura.</p><h2>Información antes de pagar</h2><p>La pantalla de compra muestra el coste de entrega y el total de prueba antes de confirmar el pedido. Todos los importes de esta maqueta incluyen un IVA orientativo.</p>`},
  devoluciones:{title:'Elegir con confianza.',eyebrow:'CAMBIOS Y DEVOLUCIONES',intro:'Esta sección está preparada para las condiciones de la tienda.',body:`<h2>Durante la prueba</h2><p>No hay compras reales ni productos enviados. Puedes añadir y quitar prendas de la bolsa tantas veces como quieras.</p><h2>Antes del lanzamiento</h2><p>La política definitiva explicará los plazos, el estado de las prendas, el procedimiento de devolución, sus costes y las condiciones aplicables a productos personalizados. Se revisará con la operativa de la tienda antes de abrir las ventas.</p><h2>Tu talla, desde el principio</h2><p>Consulta la guía de tallas y la ficha de cada referencia. La tabla actual es un ejemplo visual que se sustituirá por las medidas reales de las prendas.</p>`},
  legal:{title:'Aviso legal.',eyebrow:'INFORMACIÓN DE LA WEB',intro:'Identidad del responsable y alcance de esta vista previa.',body:`<h2>Responsable</h2><p>Publipop Soluciones en Merchandising, S.L.<br>Información fiscal y domicilio pendientes de incorporar al abrir la tienda.</p><h2>Finalidad de este entorno</h2><p>Vista previa de diseño de SPALI SPORTS. La colección, las imágenes de producto, los precios y las condiciones de compra son ilustrativos. Este entorno no constituye una tienda abierta a contratación.</p><h2>Contenido gráfico</h2><p>Las fotografías de campaña y producto son imágenes conceptuales generadas para presentar el diseño. Las características y la disponibilidad del catálogo definitivo se publicarán tras su validación.</p><h2>Dominio y marca</h2><p>spali.es es el dominio previsto, pendiente de adquisición por su titular. La identidad gráfica y la valoración registral de la marca están en revisión.</p><h2>Contacto</h2><p>Puedes revisar la pantalla de contacto desde el enlace inferior. En staging no se envían mensajes reales.</p>`},
  privacidad:{title:'Tu información, clara.',eyebrow:'PRIVACIDAD',intro:'Cómo funciona esta vista previa de diseño.',body:`<h2>Datos de prueba</h2><p>Utiliza nombres, teléfonos, correos y direcciones ficticios. El carrito, los favoritos, el estilo elegido y los pedidos de muestra se guardan en el almacenamiento local de tu navegador.</p><h2>Sin cobros ni envío de formularios</h2><p>El formulario de compra no solicita tarjetas ni comunica pedidos a una plataforma de pagos. Los formularios de contacto y novedades muestran una respuesta local de prueba y no envían correos ni suscripciones.</p><h2>Acceso al staging</h2><p>Esta vista de diseño se comparte mediante enlaces. Los datos de prueba que introduzcas permanecen en tu navegador y no se comparten con otras personas que visiten la web.</p><h2>Responsable del proyecto</h2><p>Publipop Soluciones en Merchandising, S.L. La información fiscal y el domicilio se incorporarán antes de la apertura comercial.</p><h2>Antes de abrir la tienda</h2><p>La información definitiva describirá el tratamiento de clientes, pedidos, pagos, comunicaciones y proveedores realmente conectados. Se incorporará al pasar de esta prueba al servicio comercial.</p>`},
  cookies:{title:'Tus preferencias.',eyebrow:'COOKIES Y ALMACENAMIENTO',intro:'Lo que utiliza esta maqueta para funcionar.',body:`<h2>Almacenamiento del navegador</h2><p>La vista previa utiliza almacenamiento local para recordar el carrito, los favoritos, el estilo visual y los pedidos de prueba. No incorpora herramientas de analítica ni publicidad.</p><h2>Acceso a la vista previa</h2><p>La vista de diseño puede abrirse mediante el enlace compartido, sin iniciar sesión. No incorpora herramientas de analítica ni publicidad.</p><h2>Reiniciar la prueba</h2><p>Puedes vaciar los datos de esta maqueta en este navegador. Se borrarán el carrito, los favoritos, la cuenta de demostración y los pedidos de muestra.</p><button class="button button-outline" data-action="reset-demo">Borrar datos de esta prueba</button><h2>Al abrir la tienda</h2><p>El panel de consentimiento se ajustará a las cookies y servicios que se instalen realmente.</p>`},
};
function infoPage(key) { const p=infoPages[key];return `<div class="shell">${breadcrumb([[p.eyebrow]])}${pageHead(p.title,p.intro,p.eyebrow)}<article class="rich-text legal-content">${p.body}</article><div class="section support-callout">${arrowLink('ayuda','Ir al centro de ayuda')}${arrowLink('contacto','Contacto')}</div></div>`; }
function notFound(){return `<div class="shell">${pageHead('Nos hemos salido de la pista.','La página que buscas no está en esta vista previa.','404')}${empty('Volvemos al juego.','Puedes continuar en la colección o volver al inicio.','','Volver al inicio')}</div>`;}

function dialogs() {
  return `<dialog id="cart-drawer" class="drawer" aria-labelledby="drawer-title"><div class="drawer-header"><h2 id="drawer-title">Tu bolsa</h2><button class="icon-button" data-action="close-dialog" aria-label="Cerrar bolsa">${icon('close')}</button></div><div class="drawer-body" id="drawer-content"></div><div class="drawer-footer" id="drawer-footer"></div></dialog><dialog id="search-dialog" class="search-overlay" aria-labelledby="search-title"><div class="drawer-header"><h2 id="search-title">¿Qué va contigo?</h2><button class="icon-button" data-action="close-dialog" aria-label="Cerrar búsqueda">${icon('close')}</button></div><form id="search-form"><label for="search-query" class="sr-only">Buscar en la colección</label><div class="search-input"><input id="search-query" name="q" type="search" placeholder="Camiseta, pádel, entrenamiento…" maxlength="100"><button class="icon-button" type="submit" aria-label="Buscar">${icon('arrow')}</button></div></form><div class="search-suggestions"><span class="eyebrow">EXPLORA TU LÍNEA</span>${a('coleccion','Equipo','',{linea:'equipo'})}${a('coleccion','Pareja','',{linea:'padel'})}${a('coleccion','Individual','',{linea:'entrenamiento'})}</div></dialog><div class="toast" id="toast" role="status" aria-live="polite" hidden></div>`;
}
let stopVisuals=()=>{};
function render({scroll=true}={}) {
  stopVisuals();
  const r=routeInfo();document.documentElement.dataset.style=view;
  const titleMap={inicio:'Tu forma de jugar',coleccion:'La colección',producto:getProduct(r.id)?.name||'Producto',carrito:'Tu bolsa',pago:'Finalizar la prueba',cuenta:'Tu espacio',favoritos:'Favoritos',historia:'Somos SPALI',ayuda:'Centro de ayuda','guia-tallas':'Guía de tallas',contacto:'Contacto',confirmacion:'Pedido de prueba',...Object.fromEntries(Object.entries(infoPages).map(([k,v])=>[k,v.eyebrow]))};
  document.title=`${titleMap[r.page]||'Página no encontrada'} · SPALI SPORTS · Vista previa`;
  const content=r.page==='inicio'?home():r.page==='coleccion'?collection(r.params):r.page==='producto'?productDetail(r.id,r.params.get('color')||''):r.page==='carrito'?cartPage():r.page==='pago'?checkout():r.page==='confirmacion'?confirmation(r.id):r.page==='cuenta'?account():r.page==='favoritos'?favoritesPage():r.page==='historia'?story():r.page==='guia-tallas'?sizeGuide():r.page==='ayuda'?helpPage():r.page==='contacto'?contact():infoPages[r.page]?infoPage(r.page):notFound();
  app.innerHTML=header()+`<main id="contenido" tabindex="-1">${content}</main>`+footer()+dialogs();
  const stopShooting=mountShooting(app);
  const stopProducts=mountProductSlides(app);
  stopVisuals=()=>{stopShooting();stopProducts();};
  if(r.page==='pago')updateCheckoutShipping();
  if(scroll)window.scrollTo({top:0,behavior:'instant'});
}
function toast(text) { const el=$('#toast');if(!el)return;clearTimeout(toastTimer);el.textContent=text;el.hidden=false;toastTimer=setTimeout(()=>el.hidden=true,3800); }
function persistCart(){cart=normalizeCart(cart);storage.set('cart',cart);}
function updateHeaderCount(){const count=cartSummary(cart).count;const badge=$('.cart-badge');if(badge){badge.textContent=count;badge.hidden=!count;}const toggle=$('.cart-toggle');if(toggle)toggle.setAttribute('aria-label',`Abrir bolsa, ${count} ${count===1?'artículo':'artículos'}`);}
function openDrawer(){const dialog=$('#cart-drawer');if(!dialog)return;fillDrawer();dialog.showModal();}
function fillDrawer(){const s=cartSummary(cart,{code:promo,shipping});$('#drawer-content').innerHTML=cart.length?`<p class="help">${s.count} ${s.count===1?'artículo':'artículos'} · Tu selección para la próxima jugada.</p>${cart.map(l=>lineItem(l)).join('')}`:empty('La bolsa está vacía.','Encuentra tu siguiente prenda.');$('#drawer-footer').innerHTML=cart.length?`<div class="summary-total"><span>Total de prueba</span><strong>${fmtPrice(s.total)}</strong></div>${a('carrito',`Ver mi bolsa ${icon('arrow')}`,'button')}${a('pago','Continuar como invitado','text-link')}<p class="help">IVA y entrega de prueba incluidos.</p>`:'';}
function updateCheckoutShipping(){const fields=$('#address-fields');if(!fields)return;const isPickup=$('input[name="shipping"]:checked')?.value==='pickup';fields.hidden=isPickup;$$('input',fields).forEach(input=>{input.required=!isPickup;input.disabled=isPickup;});shipping=$('input[name="shipping"]:checked')?.value||'standard';const summary=$('#checkout-summary');if(summary)summary.innerHTML=summaryRows(shipping);}
function changeCart(fn){cart=fn(cart);persistCart();updateHeaderCount();if($('#cart-drawer')?.open)fillDrawer();else render({scroll:false});}

document.addEventListener('click',event=>{
  const target=event.target.closest('[data-action]');if(!target)return;
  const action=target.dataset.action;
  if(action==='style'){view=target.dataset.style;storage.set('view',view);const url=new URL(location.href);url.searchParams.set('estilo',view);history.replaceState(null,'',url);render({scroll:false});}
  else if(action==='menu'){const menu=$('#mobile-menu');menu.hidden=!menu.hidden;target.setAttribute('aria-expanded',String(!menu.hidden));target.setAttribute('aria-label',menu.hidden?'Abrir menú':'Cerrar menú');}
  else if(action==='search'){searchOpener=target;$('#search-dialog').showModal();$('#search-query').focus();}
  else if(action==='cart')openDrawer();
  else if(action==='close-dialog'){target.closest('dialog')?.close();}
  else if(action==='favorite'){
    const id=target.dataset.id,product=getProduct(id);if(!product)return;
    favorites=favorites.includes(id)?favorites.filter(v=>v!==id):[...favorites,id];storage.set('favorites',favorites);
    const active=favorites.includes(id);
    if(routeInfo().page==='favoritos')render({scroll:false});
    else $$('[data-action="favorite"]').filter(button=>button.dataset.id===id).forEach(button=>{
      button.classList.toggle('active',active);
      button.setAttribute('aria-pressed',String(active));
      button.setAttribute('aria-label',`${active?'Quitar de':'Añadir a'} favoritos${button.classList.contains('detail-favorite')?'':': '+product.name}`);
    });
    toast(active?'Guardado en tus favoritos.':'Prenda eliminada de favoritos.');
  }
  else if(action==='product-qty'){const input=$('#product-form [name="qty"]');input.value=Math.max(1,Math.min(10,Number(input.value||1)+Number(target.dataset.delta)));}
  else if(action==='cart-qty'){const line=cart.find(l=>l.key===target.dataset.key);if(line)changeCart(c=>updateQuantity(c,line.key,line.qty+Number(target.dataset.delta)));}
  else if(action==='remove'){changeCart(c=>removeItem(c,target.dataset.key));toast('Prenda eliminada de la bolsa.');}
  else if(action==='logout'){profile=null;storage.set('profile',null);render({scroll:false});toast('Has salido del espacio de prueba.');}
  else if(action==='download-order'){const order=orders.find(o=>o.id===target.dataset.order);if(!order)return;const blob=new Blob([JSON.stringify(order,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`spali-${order.id}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  else if(action==='reset-demo'){cart=[];favorites=[];orders=[];profile=null;promo='';for(const[key,val]of Object.entries({cart,favorites,orders,profile,promo}))storage.set(key,val);render({scroll:false});toast('Datos de prueba borrados de este navegador.');}
});
document.addEventListener('click',event=>{const dialog=event.target;if(dialog.tagName==='DIALOG'){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
document.addEventListener('close',event=>{if(event.target.id==='search-dialog')searchOpener?.focus();},true);
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='personalize-toggle'){$('#personalize-fields').hidden=!el.checked;$('#custom-name').required=el.checked;if(el.checked)$('#custom-name').focus();}
  else if(el.name==='color'&&el.closest('#product-form')){
    const product=getProduct(el.closest('#product-form').dataset.id);
    if(!product||!product.colors.some(color=>color.name===el.value))return;
    $('.selected-color').textContent=el.value;
    $$('.product-gallery .product-image').forEach((image,index)=>{image.outerHTML=productImage(product,index===0?'eager':'lazy',el.value);});
    const url=new URL(location.href);
    url.hash=href('producto/'+product.id,{color:el.value});
    history.replaceState(history.state,'',url);
  }
  else if(el.dataset.cartQty)changeCart(c=>updateQuantity(c,el.dataset.cartQty,el.value));
  else if(el.id==='sort-select'){const r=routeInfo();r.params.set('orden',el.value);location.hash='/coleccion?'+r.params;}
  else if(el.name==='shipping')updateCheckoutShipping();
});
document.addEventListener('input',event=>{if(event.target.closest('#checkout-form')){const error=document.querySelector('[data-error="'+event.target.name+'"]');if(error)error.textContent='';event.target.removeAttribute('aria-invalid');document.querySelector('#checkout-error').textContent='';}if(event.target.id==='custom-name'){$('#name-preview').textContent=event.target.value.toLocaleUpperCase('es')||'TU NOMBRE';}});
document.addEventListener('submit',event=>{
  const form=event.target;event.preventDefault();
  if(form.id==='product-form'){
    const fd=new FormData(form),p=getProduct(form.dataset.id);if(!p)return;
    if(!fd.get('size')){$('#product-error').textContent='Elige una talla para continuar.';$('[name="size"]',form)?.focus();return;}
    if(fd.get('personalize')&&!/^[\p{L}\p{N} ]{1,15}$/u.test(String(fd.get('customName')||'').trim())){$('#product-error').textContent='Usa hasta 15 caracteres: letras, números y espacios.';$('#custom-name').focus();return;}
    cart=addItem(cart,{id:p.id,size:fd.get('size'),color:fd.get('color'),customName:fd.get('personalize')?fd.get('customName'):''},Number(fd.get('qty'))||1);persistCart();updateHeaderCount();$('#product-error').textContent='';openDrawer();
  } else if(form.id==='filters-form'){const params=new URLSearchParams();for(const[k,v]of new FormData(form))if(v)params.set(k,v);const sort=$('#sort-select')?.value;if(sort&&sort!=='coleccion')params.set('orden',sort);location.hash='/coleccion'+(params.size?'?'+params:'');}
  else if(form.id==='search-form'){const q=String(new FormData(form).get('q')||'').trim();$('#search-dialog').close();location.hash='/coleccion'+(q?'?q='+encodeURIComponent(q):'');}
  else if(form.id==='coupon-form'){const code=String(new FormData(form).get('code')||'').trim().toUpperCase();if(code&&code!=='SPALI10'){$('#coupon-feedback').textContent='Ese código no está disponible. Para la prueba puedes usar SPALI10.';$('#coupon-feedback').classList.add('error');return;}promo=code;storage.set('promo',promo);render({scroll:false});toast(code?'Código de prueba aplicado.':'Código retirado.');}
  else if(form.id==='checkout-form'){
    const fd=new FormData(form);const data=Object.fromEntries(fd);data.consent=fd.has('consent');data.code=promo;
    const result=prepareOrder(cart,data);$$('[data-error]',form).forEach(el=>el.textContent='');$$('input',form).forEach(el=>el.removeAttribute('aria-invalid'));
    if(!result.valid){for(const[key,message]of Object.entries(result.errors)){const el=$(`[data-error="${key}"]`,form);if(el)el.textContent=message;const input=$(`[name="${key}"]`,form);if(input)input.setAttribute('aria-invalid','true');}$('#checkout-error').textContent='Revisa los campos indicados para completar el pedido de prueba.';$('[aria-invalid="true"]',form)?.focus();return;}
    orders=[result.order,...orders].slice(0,20);storage.set('orders',orders);cart=[];persistCart();promo='';storage.set('promo','');location.hash='/confirmacion/'+encodeURIComponent(result.order.id);
  } else if(form.id==='account-form'){const fd=new FormData(form);profile={name:String(fd.get('account-name')||'').trim().slice(0,80),email:String(fd.get('account-email')||'').trim().slice(0,254)};if(!profile.name||!profile.email)return;storage.set('profile',profile);render({scroll:false});toast('Espacio de prueba preparado.');}
  else if(form.id==='newsletter-form'){const feedback=$('.form-feedback',form);feedback.textContent='Formulario comprobado. No se ha realizado ninguna suscripción.';form.reset();}
  else if(form.id==='contact-form'){const feedback=$('.form-feedback',form);feedback.textContent='Mensaje de prueba preparado correctamente. No se ha enviado ningún correo.';form.reset();}
});
document.addEventListener('click',event=>{const anchor=event.target.closest('a[href^="#"]');if(!anchor)return;const value=anchor.getAttribute('href');if(value.startsWith('#/')||value==='#')return;const target=document.getElementById(value.slice(1));if(target){event.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});target.focus({preventScroll:true});}});
window.addEventListener('hashchange',()=>render());
render();
